const TIME_LIMIT: int = 1924;      // 120 shell buffer + 1800 source window + 4 margin
const OPENING_BUFFER: int = 120;
const SRC_LIFE: int = 2300;        // Boss(): lifeSet(2300) for spell 34-37
const TALISMAN_COLOR: int = 13;    // etSprite(0, 11, 13)

// One BossCard1_at wave's EX chain: ANIM(instant) -> WAIT 120 -> ANGLE_ACCEL 120.
// av = %B, the per-wave angular velocity (BAM/frame); accel = ANGLE_ACCEL r (px/frame^2).
xformdef TALISMAN_ACCEL(av: angle, accel: fx) {
    wait(120);          // EX WAIT a=120: motion keeps running, cursor parked
    set_ang_vel(av);    // ANGLE_ACCEL s
    set_accel(accel);   // ANGLE_ACCEL r: per-frame speed increment
    wait(120);          // ANGLE_ACCEL a=120
    set_ang_vel(0deg);
    set_accel(0fx);
}

// BossCard1_at(): one call = D waves emitted one per frame.
// dir is the sign of %F0: +1 = +0.02 rad/frame, -1 = -0.02 rad/frame.
sub talisman_stream(dir: int) {
    var rank: int = global(GVAR_RANK);
    var waves: int = 120;       // diffI($D, 120, 200, 210, 240)
    var after: int = 120;       // wait([-1]) before return
    var nway: int = 1;          // etCount(0, [-1], 1)
    var accel: fx = 0.02fx;     // etExSet r ([-1.0f] stack slot): 0.02, Lunatic 0.021
    var step_dist: fx = 1fx;    // %A = %A + 1.0f
    if rank == RANK_LUNATIC {
        waves = 240;
        after = 0;
        nway = 2;
        accel = 0.021fx;
    }
    if rank == RANK_EASY {
        step_dist = 0.8fx;      // !E: %A = %A + 1.0f then %A = %A - 0.2f
    }

    sh_reset(0);                            // etNew(0)
    sh_sprite(0, TH16_TALISMAN, TALISMAN_COLOR); // etSprite(0, 11, 13)
    sh_ring(0, 1);                          // etAim(0, 3) fixed-direction ring
    sh_count(0, nway, 1);                   // etCount(0, N, 1)
    sh_speed(0, 0.1fx, 0fx);                // etSpeed(0, 0.1f, 1.0f); M=1 uses s0 only
    sh_offset(0, 0fx, -16fx);               // etOffset(0, 0.0f, -16.0f)

    var dist: fx = 16fx;                    // %A = 16.0f
    var av0: int = 209 * dir;               // %F0 = +-0.02 rad/frame expressed in BAM/frame
    var base: int = rand(65536) - 32768;    // %C = %RANDRAD, whole -pi..pi domain
    var k: int = 0;
    while k < waves {
        // %B = %F0 - (%F0 / 240.0f) per iteration; read before the decrement.
        var av: int = (av0 * (waves - k)) / waves;
        sh_angle(0, base as angle, 0deg);   // etAngle(0, %C, 0.0f)
        sh_dist(0, dist - 0.4fx);           // etDist(%A) plus ANIM entry -4*0.1px
        sh_xform(0, TALISMAN_ACCEL(av as angle, accel));
        sh_fire(0);                         // etOn(0)
        // %C = %C + (0.08726646f * %RANDF2) + 3.883222f  (= 222.5deg +- 5deg)
        base = base + 40505 + (910 * (rand(65536) - 32768)) / 32768;
        dist = dist + step_dist;            // %A = %A + 1.0f
        k = k + 1;
        wait(1);
    }
    wait(after);
}

// Boss(): entry state is (0,128) with no residual velocity.
async sub boss_card1() {
    set_invuln(65535);
    set_hitbox(24fx);                       // setHitbox(48,48): circle branch uses w*0.5
    set_hurtbox(20fx);                      // setHurtbox(40,40): circle branch uses w*0.5
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT); // BossCard1:464 movePosTime(60, 4, 0, 128)
    wait(120);                              // BossCard1:471 "+120" time label
    var gap: int = 160;                     // caller wait([-1]): Easy 160, Lunatic 0
    if global(GVAR_RANK) == RANK_LUNATIC { gap = 0; }
    var remaining: int = 1000;              // $A = 1000; if ($A--) enters 1000 times
    while remaining > 0 {
        remaining = remaining - 1;
        talisman_stream(1);                 // %F0 = 0.02f
        wait(gap);
        talisman_stream(-1);                // %F0 = -0.02f
        wait(gap);
    }
    loop { wait(1000); }                    // BossCard1_1664 / _1684 tail
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, SRC_LIFE, 0, 0, 0, boss_card1);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    spell_begin(0, 34, pattern, TIME_LIMIT, 0, 0, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

